+  const visibleProducts =
+    activeCategory === "All"
+      ? products
+      : products.filter((product) => product.category === activeCategory);
+
+  productGrid.innerHTML = visibleProducts
+    .map(
+      (product) => `
+        <article class="product-card">
+          <div class="product-visual" style="--card-gradient: ${product.gradient}"></div>
+          <div class="product-card-content">
+            <p class="product-meta">${product.category}</p>
+            <div class="product-row">
+              <h3>${product.name}</h3>
+              <span class="tag">${product.tag}</span>
+            </div>
+            <p>${product.description}</p>
+            <div class="product-row">
+              <span class="price">${formatPrice(product.price)}</span>
+              <a class="text-link" href="#">Add to bag</a>
+            </div>
+          </div>
+        </article>
+      `
+    )
+    .join("");
+}
+
+function renderDeals() {
+  dealGrid.innerHTML = deals
+    .map(
+      (deal) => `
+        <article class="deal-card">
+          <div class="deal-visual" style="--card-gradient: ${deal.gradient}"></div>
+          <div class="deal-card-content">
+            <p class="deal-meta">Flash offer</p>
+            <div class="deal-row">
+              <h3>${deal.title}</h3>
+              <span class="badge">${deal.badge}</span>
+            </div>
+            <p>${deal.detail}</p>
+            <span class="price">${deal.price}</span>
+          </div>
+        </article>
+      `
+    )
+    .join("");
+}
+
+function renderStories() {
+  editorialGrid.innerHTML = stories
+    .map(
+      (story) => `
+        <article class="editorial-card">
+          <div class="editorial-visual" style="--card-gradient: ${story.gradient}"></div>
+          <div class="editorial-card-content">
+            <p class="editorial-meta">${story.meta}</p>
+            <h3>${story.title}</h3>
+            <p>${story.description}</p>
+            <a class="text-link" href="#">Read story</a>
+          </div>
+        </article>
+      `
+    )
+    .join("");
+}
+
+function startDealCountdown() {
+  const refreshTime = new Date();
+  refreshTime.setHours(refreshTime.getHours() + 18, 0, 0, 0);
+
+  const updateCountdown = () => {
+    const remaining = refreshTime - new Date();
+
+    if (remaining <= 0) {
+      dealCountdown.textContent = "00:00:00";
+      return;
+    }
+
+    const hours = String(Math.floor(remaining / 3600000)).padStart(2, "0");
+    const minutes = String(Math.floor((remaining % 3600000) / 60000)).padStart(2, "0");
+    const seconds = String(Math.floor((remaining % 60000) / 1000)).padStart(2, "0");
+    dealCountdown.textContent = `${hours}:${minutes}:${seconds}`;
+  };
+
+  updateCountdown();
+  window.setInterval(updateCountdown, 1000);
+}
+
+categoryFilters.addEventListener("click", (event) => {
+  const filterButton = event.target.closest("[data-category]");
+
+  if (!filterButton) {
+    return;
+  }
+
+  const nextCategory = filterButton.getAttribute("data-category") || "All";
+  renderFilters(nextCategory);
+  renderProducts(nextCategory);
+});
+
+renderFilters("All");
+renderProducts();
+renderDeals();
+renderStories();
+startDealCountdown();
+

')
